from pathlib import Path
import hashlib,json,subprocess,time
ROOT=Path(__file__).resolve().parents[2];OUT=Path(__file__).resolve().parent
expressions=['(pr-str (let [p nil] (with-precision p :rounding FLOOR (str *math-context*))))', '(pr-str ((fn [p] (with-precision p :rounding FLOOR (str *math-context*))) nil))', '(pr-str (let [p "x"] (with-precision p :rounding FLOOR (str *math-context*))))', '(pr-str ((fn [p] (with-precision p :rounding FLOOR (str *math-context*))) "x"))', '(pr-str (let [p true] (with-precision p :rounding FLOOR (str *math-context*))))', '(pr-str ((fn [p] (with-precision p :rounding FLOOR (str *math-context*))) true))', '(pr-str (let [p :x] (with-precision p :rounding FLOOR (str *math-context*))))', '(pr-str ((fn [p] (with-precision p :rounding FLOOR (str *math-context*))) :x))', '(pr-str (let [p []] (with-precision p :rounding FLOOR (str *math-context*))))', '(pr-str ((fn [p] (with-precision p :rounding FLOOR (str *math-context*))) []))', '(pr-str (let [p {}] (with-precision p :rounding FLOOR (str *math-context*))))', '(pr-str ((fn [p] (with-precision p :rounding FLOOR (str *math-context*))) {}))', '(pr-str (let [p 1267650600228229401496703205376N] (with-precision p :rounding FLOOR (str *math-context*))))', '(pr-str ((fn [p] (with-precision p :rounding FLOOR (str *math-context*))) 1267650600228229401496703205376N))', '(pr-str (let [p (biginteger 1267650600228229401496703205376N)] (with-precision p :rounding FLOOR (str *math-context*))))', '(pr-str ((fn [p] (with-precision p :rounding FLOOR (str *math-context*))) (biginteger 1267650600228229401496703205376N)))', '(pr-str (let [p 1267650600228229401496703205376/3] (with-precision p :rounding FLOOR (str *math-context*))))', '(pr-str ((fn [p] (with-precision p :rounding FLOOR (str *math-context*))) 1267650600228229401496703205376/3))']
source='(assert (= "1.12.6" (clojure-version)))\n'+''.join('(println (pr-str (pr-str (try '+e+' (catch Throwable e [:error (.getMessage e)])))))\n' for e in expressions)
(OUT/'extended-diagnostics-oracle.clj').write_text(source)
prior=json.loads((ROOT/'results/m12-wide-wit/oracle-command.json').read_text());command=prior['command'][:-1]+[str(OUT/'extended-diagnostics-oracle.clj')]
t=time.time();r=subprocess.run(command,cwd=ROOT,text=True,capture_output=True)
(OUT/'extended-diagnostics-oracle.log').write_text(r.stdout+r.stderr)
(OUT/'extended-diagnostics-oracle-command.json').write_text(json.dumps({'command':command,'exit_code':r.returncode,'seconds':time.time()-t,'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'jars':{p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in prior['jars']}},indent=2)+'\n')
assert r.returncode==0,r.stderr
values=[json.loads(x) for x in r.stdout.splitlines()];assert len(values)==len(expressions)
(OUT/'extended-diagnostics-cases.json').write_text(json.dumps(list(zip(expressions,values)),indent=2)+'\n')
for i,x in enumerate(values):print(i,x)
